if (x > 5 && x < 8)
    printf("A\n");
else if (x > 5 || x < 0)
    printf("B\n");
else
    printf("C\n");
```

exercices.code:
#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    /* À compléter : affiche a + b puis a * b */
    return 0;
}

exercices.solution:
#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    printf("%d %d\n", a + b, a * b);
    return 0;
}

exercices.code:
#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    /* À compléter : affiche « H h M min S s » */
    return 0;
}

exercices.solution:
#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int h = n / 3600;
    int m = (n % 3600) / 60;
    int s = n % 60;
    printf("%d h %d min %d s\n", h, m, s);
    return 0;
}
